// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title TokenVerifier - Verifies structured authentication tokens
/// @notice Implements multi-algorithm token verification with role-based access
library TokenLib {
    uint8 constant ALG_NONE = 0x01;
    uint8 constant ALG_HMAC = 0x02;
    uint8 constant ALG_ECDSA = 0x04;

    struct TokenHeader {
        uint8 algorithmFlags;
        uint8 version;
        uint40 issuedAt;
        uint40 expiresAt;
        address subject;
    }

    struct TokenPayload {
        bytes32 claimsHash;
        uint8 roleLevel;
        uint16 tenantId;
    }

    function decodeHeader(bytes calldata raw) internal pure returns (TokenHeader memory header) {
        require(raw.length >= 32, "Header too short");
        header.algorithmFlags = uint8(raw[0]);
        header.version = uint8(raw[1]);
        header.issuedAt = uint40(bytes5(raw[2:7]));
        header.expiresAt = uint40(bytes5(raw[7:12]));
        header.subject = address(bytes20(raw[12:32]));
    }

    function decodePayload(bytes calldata raw) internal pure returns (TokenPayload memory payload) {
        require(raw.length >= 35, "Payload too short");
        payload.claimsHash = bytes32(raw[0:32]);
        payload.roleLevel = uint8(raw[32]);
        payload.tenantId = uint16(bytes2(raw[33:35]));
    }

    /// @notice Validates algorithm flags against allowed algorithms
    /// @param tokenAlgFlags The algorithm flags from the token header
    /// @param allowedAlgMask The bitmask of algorithms the verifier accepts
    /// @return True if the token's algorithm is permitted
    function validateAlgorithm(uint8 tokenAlgFlags, uint8 allowedAlgMask) internal pure returns (bool) {
        // Check that the token's algorithm is within the allowed set
        // Token may specify exactly one algorithm bit
        require(tokenAlgFlags != 0, "No algorithm specified");
        // Ensure only one bit is set (power of 2 check)
        require(tokenAlgFlags & (tokenAlgFlags - 1) == 0, "Multiple algorithms");
        // Verify the token's algorithm is in the allowed mask
        return (tokenAlgFlags & allowedAlgMask) == tokenAlgFlags;
    }
}

contract TokenVerifier {
    using TokenLib for bytes;

    // State variables
    mapping(uint16 => address) public tenantSigners;
    mapping(uint16 => uint8) public tenantAllowedAlgorithms;
    mapping(address => bool) public globalAdmins;
    mapping(uint16 => mapping(address => uint8)) public userRoles;

    // Security: track used token hashes to prevent replay
    mapping(bytes32 => bool) public usedTokens;

    // Events
    event TokenVerified(address indexed subject, uint16 indexed tenantId, uint8 roleLevel);
    event TenantConfigured(uint16 indexed tenantId, address signer, uint8 algorithms);
    event AccessGranted(address indexed user, uint16 indexed tenantId, uint8 roleLevel);

    modifier onlyAdmin() {
        require(globalAdmins[msg.sender], "Not admin");
        _;
    }

    constructor() {
        globalAdmins[msg.sender] = true;
    }

    /// @notice Configure a tenant's verification parameters
    /// @param tenantId The tenant identifier
    /// @param signer The authorized signer address for this tenant
    /// @param allowedAlgorithms Bitmask of allowed algorithms (should NOT include ALG_NONE=0x01)
    function configureTenant(
        uint16 tenantId,
        address signer,
        uint8 allowedAlgorithms
    ) external onlyAdmin {
        require(signer != address(0), "Invalid signer");
        // Security: never allow ALG_NONE in production
        require(allowedAlgorithms & TokenLib.ALG_NONE == 0, "ALG_NONE not permitted");
        require(allowedAlgorithms != 0, "Must allow at least one algorithm");

        tenantSigners[tenantId] = signer;
        tenantAllowedAlgorithms[tenantId] = allowedAlgorithms;

        emit TenantConfigured(tenantId, signer, allowedAlgorithms);
    }

    /// @notice Verify a token and grant access
    /// @param headerRaw Raw header bytes
    /// @param payloadRaw Raw payload bytes  
    /// @param signature The cryptographic signature (ignored for ALG_NONE)
    function verifyToken(
        bytes calldata headerRaw,
        bytes calldata payloadRaw,
        bytes calldata signature
    ) external returns (bool) {
        TokenLib.TokenHeader memory header = TokenLib.decodeHeader(headerRaw);
        TokenLib.TokenPayload memory payload = TokenLib.decodePayload(payloadRaw);

        // Temporal validation
        require(block.timestamp >= header.issuedAt, "Token not yet valid");
        require(block.timestamp <= header.expiresAt, "Token expired");
        require(header.version == 1, "Unsupported version");

        // Anti-replay
        bytes32 tokenHash = keccak256(abi.encodePacked(headerRaw, payloadRaw, signature));
        require(!usedTokens[tokenHash], "Token already used");
        usedTokens[tokenHash] = true;

        // Algorithm validation against tenant configuration
        uint8 allowedAlgs = tenantAllowedAlgorithms[payload.tenantId];
        require(allowedAlgs != 0, "Tenant not configured");
        require(
            TokenLib.validateAlgorithm(header.algorithmFlags, allowedAlgs),
            "Algorithm not allowed"
        );

        // Signature verification based on algorithm
        if (header.algorithmFlags == TokenLib.ALG_NONE) {
            // No signature verification needed
            // This path should never be reached if tenant config is correct
            revert("ALG_NONE not supported in verification");
        } else if (header.algorithmFlags == TokenLib.ALG_HMAC) {
            _verifyHMAC(payload.tenantId, headerRaw, payloadRaw, signature);
        } else if (header.algorithmFlags == TokenLib.ALG_ECDSA) {
            _verifyECDSA(payload.tenantId, headerRaw, payloadRaw, signature);
        } else {
            revert("Unknown algorithm");
        }

        // Grant access
        userRoles[payload.tenantId][header.subject] = payload.roleLevel;

        emit TokenVerified(header.subject, payload.tenantId, payload.roleLevel);
        emit AccessGranted(header.subject, payload.tenantId, payload.roleLevel);

        return true;
    }

    function _verifyHMAC(
        uint16 tenantId,
        bytes calldata headerRaw,
        bytes calldata payloadRaw,
        bytes calldata signature
    ) internal view {
        address signer = tenantSigners[tenantId];
        bytes32 messageHash = keccak256(abi.encodePacked(headerRaw, payloadRaw));
        bytes32 expectedSig = keccak256(abi.encodePacked(messageHash, signer));
        require(keccak256(signature) == expectedSig, "Invalid HMAC");
    }

    function _verifyECDSA(
        uint16 tenantId,
        bytes calldata headerRaw,
        bytes calldata payloadRaw,
        bytes calldata signature
    ) internal view {
        require(signature.length == 65, "Invalid signature length");
        address signer = tenantSigners[tenantId];
        bytes32 messageHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n", headerRaw, payloadRaw));

        bytes32 r = bytes32(signature[0:32]);
        bytes32 s = bytes32(signature[32:64]);
        uint8 v = uint8(signature[64]);

        // Fix: prevent ECDSA signature malleability.
        // Reject 's' values in the upper half of the curve order and
        // reject non-canonical 'v' values.
        require(
            uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0,
            "Invalid signature 's' value (malleable)"
        );
        require(v == 27 || v == 28, "Invalid signature 'v' value");

        address recovered = ecrecover(messageHash, v, r, s);
        require(recovered != address(0), "Invalid signature");
        require(recovered == signer, "Signer mismatch");
    }

    /// @notice Check if a user has a minimum role level for a tenant
    function hasAccess(uint16 tenantId, address user, uint8 minRole) external view returns (bool) {
        return userRoles[tenantId][user] >= minRole;
    }

    function addAdmin(address admin) external onlyAdmin {
        require(admin != address(0), "Invalid admin");
        globalAdmins[admin] = true;
    }
}
